WITH joined_data AS (SELECT s.cds, s.rtype, s.avgscrread, s.avgscrmath, s.avgscrwrite, s.enroll12, s.cds AS school_cds, fr.cdscode AS frpm_cdscode, fr."School Type" AS school_type, fr."Enrollment (K-12)" AS enrollment_k12, fr."Charter Funding Type" AS charter_funding_type FROM satscores s JOIN schools schools ON s.cds = schools.cdscode JOIN frpm fr ON fr.cdscode = schools.cdscode WHERE schools.cdscode IS NOT NULL AND fr.cdscode IS NOT NULL) SELECT school_type, charter_funding_type, AVG(avgscrread) AS avg_read_score, AVG(avgscrmath) AS avg_math_score, AVG(avgscrwrite) AS avg_write_score, AVG(enrollment_k12) AS avg_enrollment FROM joined_data GROUP BY school_type, charter_funding_type;
